CREATE EXTENSION IF NOT EXISTS vector;
CREATE TABLE patient_context (id integer PRIMARY KEY CHECK(id=1), version integer NOT NULL DEFAULT 0, allergies jsonb NOT NULL, conditions jsonb NOT NULL, other_medications jsonb NOT NULL);
INSERT INTO patient_context VALUES (1,0,'{"status":"unknown","items":[]}','{"status":"unknown","items":[]}','{"status":"unknown","items":[]}');
CREATE TABLE treatments (id uuid PRIMARY KEY, title text NOT NULL, reason text NOT NULL, status text NOT NULL CHECK(status IN ('draft','following','archived')), current_revision integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE TABLE treatment_drafts (treatment_id uuid PRIMARY KEY REFERENCES treatments ON DELETE CASCADE, version integer NOT NULL, base_revision integer NOT NULL, snapshot jsonb NOT NULL);
CREATE TABLE treatment_revisions (id uuid PRIMARY KEY, treatment_id uuid NOT NULL REFERENCES treatments ON DELETE CASCADE, revision integer NOT NULL, snapshot jsonb NOT NULL, change_reason text NOT NULL, confirmed_at timestamptz NOT NULL DEFAULT now(), UNIQUE(treatment_id,revision));
CREATE TABLE documents (id uuid PRIMARY KEY, treatment_id uuid NOT NULL REFERENCES treatments ON DELETE CASCADE, storage_key uuid, sha256 text NOT NULL, filename text NOT NULL, mime text NOT NULL, bytes integer NOT NULL, generation integer NOT NULL DEFAULT 1, status text NOT NULL, attempt_count integer NOT NULL DEFAULT 0, error_code text, deleted_at timestamptz);
CREATE TABLE document_extractions (document_id uuid NOT NULL REFERENCES documents ON DELETE CASCADE, generation integer NOT NULL, extraction jsonb NOT NULL, PRIMARY KEY(document_id,generation));
CREATE TABLE evolution_entries (id uuid PRIMARY KEY, treatment_id uuid NOT NULL REFERENCES treatments ON DELETE CASCADE, kind text NOT NULL, occurred_at timestamptz NOT NULL, payload jsonb NOT NULL, original_text text, version integer NOT NULL DEFAULT 1, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE analysis_runs (id uuid PRIMARY KEY, treatment_id uuid NOT NULL REFERENCES treatments ON DELETE CASCADE, document_id uuid REFERENCES documents ON DELETE CASCADE, kind text NOT NULL, status text NOT NULL, mode text NOT NULL, request_hash text NOT NULL UNIQUE, input_snapshot jsonb NOT NULL, source_snapshot jsonb NOT NULL, result jsonb, external_consent jsonb, model text NOT NULL, prompt_version text NOT NULL, error_code text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE questions (id uuid PRIMARY KEY, treatment_id uuid NOT NULL REFERENCES treatments ON DELETE CASCADE, text text NOT NULL, origin text NOT NULL, analysis_id uuid REFERENCES analysis_runs ON DELETE SET NULL, status text NOT NULL DEFAULT 'pending', reported_answer text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE knowledge_sources (id text PRIMARY KEY, metadata jsonb NOT NULL, active boolean NOT NULL DEFAULT true, reviewed_at timestamptz NOT NULL);
CREATE TABLE knowledge_chunks (id text PRIMARY KEY, source_id text NOT NULL REFERENCES knowledge_sources, text text NOT NULL, scope text NOT NULL CHECK(scope IN ('product','substance_route_formulation')), hash text NOT NULL, embedding vector(1536));
CREATE TABLE ai_usage (id uuid PRIMARY KEY, analysis_id uuid REFERENCES analysis_runs ON DELETE SET NULL, operation text NOT NULL, day date NOT NULL DEFAULT (now() AT TIME ZONE 'UTC')::date, model text NOT NULL, reserved_cents integer NOT NULL CHECK(reserved_cents=3), status text NOT NULL, input_tokens integer, output_tokens integer);
CREATE TABLE demo_cases (id text PRIMARY KEY, treatment_id uuid NOT NULL REFERENCES treatments ON DELETE CASCADE, version integer NOT NULL, snapshot_hash text NOT NULL, document_text_hash text NOT NULL, context_version integer NOT NULL, dependencies_hash text);
CREATE INDEX evolution_period ON evolution_entries(treatment_id,occurred_at);
CREATE INDEX treatment_active ON treatments(status) WHERE deleted_at IS NULL;
